    def test_mixed_scenario(self, tmp_path, capsys):
        # Prior day data
        prior_dir = tmp_path / "2020-01-01"
        prior_dir.mkdir()
        (prior_dir / f"fixable{SESSION_FILE_SUFFIX}").write_text(
            json.dumps({"session_id": "fixable", "cost": {"total_cost_usd": 2.00}})
        )

        today_dir = tmp_path / date.today().isoformat()
        today_dir.mkdir()

        # File that already has _prior_cost (skipped)
        (today_dir / f"has-prior{SESSION_FILE_SUFFIX}").write_text(
            json.dumps({"session_id": "has-prior", "_prior_cost": 1.0})
        )
        # File that will be fixed (prior > 0)
        (today_dir / f"fixable{SESSION_FILE_SUFFIX}").write_text(
            json.dumps({"session_id": "fixable", "cost": {"total_cost_usd": 5.00}})
        )
        # File with no prior (skipped)
        (today_dir / f"no-prior{SESSION_FILE_SUFFIX}").write_text(
            json.dumps({"session_id": "no-prior", "cost": {"total_cost_usd": 1.00}})
        )
        # Malformed JSON (skipped via continue)
        (today_dir / f"corrupt{SESSION_FILE_SUFFIX}").write_text("{bad")
        # Non-JSON file (skipped via suffix check)
        (today_dir / "readme.txt").write_text("ignore me")

        with mock.patch("scripts.backfill_prior_cost.BASE_DIR", tmp_path):
            main()

        output = capsys.readouterr().out
        assert "1 fixed, 2 skipped" in output
